E = "OSH-03"   # 勞動檢查法
D = "OSH-04"   # 勞動檢查法施行細則
Q = [

# ===== 勞動檢查法 =====
(E,"第1條",1,"勞檢法-總則",
 "勞動檢查法之立法目的為何？",
 ["為實施勞動檢查，貫徹勞動法令之執行、維護勞雇雙方權益、安定社會、發展經濟","為保障勞工之職業安全與健康，防止職業災害，並促進勞資關係之和諧發展","為健全勞動檢查體系，加強事業單位自主管理，減輕主管機關檢查之負擔","為統一各業勞動條件標準，保障勞工基本生活，並提高事業單位之生產力"],"a",
 "第1條：為實施勞動檢查，貫徹勞動法令之執行、維護勞雇雙方權益、安定社會、發展經濟，特制定本法。本法第4條並定勞動檢查事項範圍包括本法應執行檢查之事項、勞動基準法令、職業安全衛生法令及其他依勞動法令應辦理之事項。防止職業災害則為職業安全衛生法第1條之立法目的。",
 "What is the legislative purpose of the Labor Inspection Act?",
 ["To carry out inspection, enforce labor laws, protect both sides, stabilise society and develop the economy","To safeguard occupational safety and health, prevent occupational accidents and foster harmony","To strengthen the inspection system, promote self-management and lighten the burden on the authority","To unify working condition standards across industries, protect livelihoods and raise productivity"],
 "Article 1; compare Article 1 of the OSH Act."),

(E,"第2條",1,"勞檢法-主管機關",
 "勞動檢查法所稱之主管機關，各級分別為何？",
 ["在中央為勞動部；在直轄市為直轄市政府；在縣（市）為縣（市）政府","在中央為行政院勞工委員會；在地方為各該勞動檢查機構及其分支單位","在中央為勞動部職業安全衛生署；在地方為各直轄市及縣（市）勞工局","在中央為勞動部；在直轄市及縣（市）均為當地所設之勞動檢查機構"],"a",
 "第2條：本法所稱主管機關：在中央為勞動部；在直轄市為直轄市政府；在縣（市）為縣（市）政府。應與第3條第1款之勞動檢查機構區別，勞動檢查機構係指中央或直轄市主管機關或有關機關為辦理勞動檢查業務所設置之專責檢查機構。",
 "Who are the competent authorities under the Labor Inspection Act?",
 ["The Ministry of Labor centrally; the municipal government; and the county or city government","The Council of Labor Affairs centrally; and locally the inspection agencies and their branches","The Occupational Safety and Health Administration centrally; and locally the labor bureaus","The Ministry of Labor centrally; and in municipalities and counties the inspection agencies"],
 "Article 2; compare Article 3, Subparagraph 1."),

(E,"第5條",2,"勞檢法-檢查機構",
 "勞動檢查應由何者辦理？其組織及員額設置基準如何訂定？",
 ["由中央主管機關設勞動檢查機構或授權直轄市主管機關、有關機關專設檢查機構辦理，組織及員額設置基準由中央主管機關擬訂報請行政院核定","由各直轄市及縣（市）主管機關分別設立檢查機構辦理，其組織及員額設置基準由各該地方立法機關以自治條例定之並報中央備查","由中央主管機關委託代行檢查機構統籌辦理，其組織及員額設置基準由中央主管機關會商各該代行檢查機構後公告實施","由中央主管機關設勞動檢查機構專責辦理而不得授權，其員額設置基準依受檢查事業單位之數量由檢查機構自行核定"],"a",
 "第5條：勞動檢查由中央主管機關設勞動檢查機構或授權直轄市主管機關或有關機關專設勞動檢查機構辦理之；勞動檢查機構認有必要時，得會同縣（市）主管機關檢查。授權之勞動檢查應依本法有關規定辦理，並受中央主管機關之指揮監督。其組織、員額設置基準，依受檢查事業單位之數量、地區特性，由中央主管機關擬訂，報請行政院核定之。",
 "Who carries out labor inspection, and how are the organisation and staffing standards set?",
 ["The ministry sets up agencies or authorises municipal or relevant agencies; staffing standards go to the Executive Yuan","Each municipality and county sets up its own agency, and staffing standards are set by local by-laws filed centrally","The ministry entrusts accredited inspection agencies, and staffing standards are announced after consultation","The ministry alone may set up agencies with no delegation, and each agency fixes its own staffing by caseload"],
 "Article 5 of the Labor Inspection Act."),

(E,"第8條",1,"勞檢法-檢查員",
 "勞動檢查員之任用，其法令依據及遴用標準之訂定機關為何？",
 ["除適用公務人員有關法令之規定外，其遴用標準由中央主管機關定之","除適用公務人員有關法令之規定外，並應經專門職業及技術人員考試及格","不適用公務人員任用法令，改由各勞動檢查機構自行公開甄選並進用之","除適用公務人員有關法令之規定外，其遴用標準由行政院人事總處定之"],"a",
 "第8條：勞動檢查員之任用，除適用公務人員有關法令之規定外，其遴用標準由中央主管機關定之。第9條並定勞動檢查員應接受專業訓練，訓練辦法由中央主管機關定之；施行細則第8條定專業訓練指新進人員之職前訓練、現職人員之在職訓練及進修。",
 "How are labor inspectors appointed, and who sets the selection standards?",
 ["Civil service laws apply, and the selection standards are set by the central competent authority","Civil service laws apply, and the inspector must also pass the professional and technical exam","Civil service laws do not apply; each inspection agency recruits and hires openly on its own","Civil service laws apply, and the selection standards are set by the personnel administration"],
 "Article 8; see also Article 9."),

(E,"第9條",1,"勞檢法-檢查員",
 "關於勞動檢查員之專業訓練，本法規定為何？",
 ["勞動檢查員應接受專業訓練，其訓練辦法由中央主管機關定之","勞動檢查員應接受專業訓練，其訓練辦法由各勞動檢查機構定之","勞動檢查員得視業務需要參加訓練，其課程由勞動檢查機構排定","勞動檢查員應每年接受在職訓練，其訓練辦法由行政院統一訂定"],"a",
 "第9條：勞動檢查員應接受專業訓練；前項訓練辦法，由中央主管機關定之。施行細則第8條定專業訓練指新進人員之職前訓練、現職人員之在職訓練及進修；第9條並定新進勞動檢查員未經職前訓練合格前，勞動檢查機構不得指派其單獨執行檢查職務，但特殊情況經陳報中央主管機關核准者不在此限。",
 "What does the Act provide on professional training of labor inspectors?",
 ["Inspectors must receive professional training, and the ministry sets the training regulations","Inspectors must receive professional training, and each agency sets its own training rules","Inspectors may attend training as needed, with courses scheduled by the inspection agency","Inspectors must have in-service training yearly, under rules set by the Executive Yuan"],
 "Article 9; see Enforcement Rules Articles 8 and 9."),

(E,"第10條",1,"勞檢法-檢查員",
 "勞動檢查員執行檢查職務時，其指派方式為何？",
 ["由勞動檢查機構依其專長及任務之特性指派，執行本法第四條所定之職務","由中央主管機關統一造冊指派，並輪調至各勞動檢查機構執行檢查職務","由事業單位所在地之直轄市主管機關指派，並受勞動檢查機構之監督","由勞動檢查機構依到職年資順序輪流指派，以確保檢查案件分配公平"],"a",
 "第10條：勞動檢查員由勞動檢查機構依其專長及任務之特性指派，執行第4條所定之職務。第4條所定勞動檢查事項範圍包括依本法規定應執行檢查之事項、勞動基準法令規定之事項、職業安全衛生法令規定之事項及其他依勞動法令應辦理之事項。",
 "How are labor inspectors assigned to carry out their duties?",
 ["The inspection agency assigns them by expertise and task character for the Article 4 duties","The ministry keeps a central roster and rotates inspectors among the inspection agencies","The municipal authority where the enterprise sits assigns them under the agencys supervision","The agency assigns them in turn by seniority so that cases are distributed evenly and fairly"],
 "Article 10 of the Labor Inspection Act."),

(E,"第12條",1,"勞檢法-檢查員",
 "勞動檢查員與受檢查事業單位有利害關係時，應如何處理？",
 ["應自行迴避，不得執行職務，其迴避辦法由中央主管機關定之","得聲請迴避而不必然停止職務，其准駁由勞動檢查機構決定之","僅於本人或配偶曾受僱於該事業單位時始須迴避，其餘不受限","應自行迴避，不得執行職務，其迴避辦法由行政院另行訂定之"],"a",
 "第12條：勞動檢查員與受檢查事業單位有利害關係者，應自行迴避，不得執行職務；其辦法，由中央主管機關定之。第21條並規定第11條及第12條之規定，於代行檢查員適用之；第23條第2項則定第11條第1項第2款及第12條之規定，於陪同鑑定人員適用之。",
 "What must an inspector do if he has an interest in the enterprise to be inspected?",
 ["He must recuse himself and may not act; the ministry lays down the recusal regulations","He may apply for recusal without stopping work; the agency decides whether to allow it","He must recuse only if he or a spouse once worked there; otherwise there is no limit","He must recuse himself and may not act; the Executive Yuan lays down the regulations"],
 "Article 12; applied to accredited inspectors by Article 21."),

(E,"第18條",1,"勞檢法-代行檢查",
 "代行檢查機構之資格條件、責任、考評及獎勵辦法，與代行檢查員之資格及訓練，應由何機關訂定？",
 ["代行檢查機構之資格條件與所負責任、考評及獎勵辦法，暨代行檢查員之資格、訓練，均由中央主管機關定之","代行檢查機構之資格條件與所負責任、考評及獎勵辦法，暨代行檢查員之資格、訓練，均由行政院定之","代行檢查機構之資格條件由中央主管機關定之；代行檢查員之資格及訓練，則由各該機構自行訂定","代行檢查機構及代行檢查員之資格、訓練及考評，由勞動檢查機構擬訂後報請中央主管機關核定"],"a",
 "第18條：代行檢查機構之資格條件與所負責任、考評及獎勵辦法，暨代行檢查員之資格、訓練，由中央主管機關定之。第3條第2款定代行檢查機構指由中央主管機關指定為辦理危險性機械或設備檢查之行政機關、學術機構或非營利法人；第17條並定必要時得指定代行檢查機構派代行檢查員實施檢查。",
 "Who sets the qualifications, duties, appraisal and rewards for accredited inspection agencies and inspectors?",
 ["The central competent authority sets all of them, covering both the agencies and their inspectors","The Executive Yuan sets all of them, covering both the agencies and their inspectors alike","The ministry sets the agency qualifications, while each agency sets its own inspector training","Inspection agencies draft them for the qualifications, training and appraisal, subject to approval"],
 "Article 18 of the Labor Inspection Act."),

(E,"第19條",2,"勞檢法-代行檢查",
 "代行檢查業務之性質及其收費標準，本法如何規定？",
 ["代行檢查業務為非營利性質，收費標準以收支平衡為原則，由代行檢查機構列計後報請中央主管機關核定","代行檢查業務得酌收合理利潤，收費標準由代行檢查機構自行訂定，並報請勞動檢查機構備查後實施","代行檢查業務為非營利性質，收費標準由中央主管機關統一訂定並公告，各機構不得自行列計費用","代行檢查業務所需經費由中央主管機關編列預算支應，不得向受檢查之事業單位收取任何之費用"],"a",
 "第19條：代行檢查業務為非營利性質，其收費標準之計算，以收支平衡為原則，由代行檢查機構就其代行檢查所需經費列計標準，報請中央主管機關核定之。第20條並定代行檢查機構擬變更代行檢查業務時，應向中央主管機關申請核准。",
 "What is the nature of accredited inspection work and how are its fees set?",
 ["It is non-profit; fees are calculated to break even and submitted for approval by the ministry","It may earn a reasonable profit; each agency sets its fees and files them with the inspection agency","It is non-profit; the ministry sets a uniform fee schedule and no agency may compute its own","Its costs come from the ministry budget, and no fee may be charged to the inspected enterprise"],
 "Article 19 of the Labor Inspection Act."),

(E,"第20條",2,"勞檢法-代行檢查",
 "代行檢查機構擬變更其代行檢查業務時，應踐行何種程序？",
 ["應檢附擬增減之機械或設備種類、檢查類別、區域等資料，向中央主管機關申請核准","應檢附擬增減之機械或設備種類、檢查類別、區域等資料，向勞動檢查機構報請備查","應於變更後三十日內，將變更事項及相關資料函報中央主管機關備查並公告周知","應先經所在地直轄市主管機關同意，再檢附相關資料報請行政院核定後始得實施"],"a",
 "第20條：代行檢查機構擬變更代行檢查業務時，應檢附擬增減之機械或設備種類、檢查類別、區域等資料，向中央主管機關申請核准。施行細則第17條並定代行檢查機構得實施之檢查，指定期檢查及其他經中央主管機關指定公告之檢查；第18條定行政機關為代行檢查機構者，其範圍以所屬事業所有之危險性機械設備為限。",
 "What must an accredited agency do to change the scope of its inspection business?",
 ["Apply to the central authority for approval with data on the machinery, categories and areas","File with the inspection agency for the record, with data on the machinery, categories and areas","Report the change to the central authority within thirty days and announce it to the public","Obtain the consent of the municipal authority and then seek Executive Yuan approval first"],
 "Article 20 of the Labor Inspection Act."),

(E,"第21條",1,"勞檢法-代行檢查",
 "本法有關勞動檢查員之哪些規定，於代行檢查員一併適用？",
 ["第十一條及第十二條之規定，即禁止行為與利害關係應自行迴避之規定","第十三條及第十四條之規定，即事先通知限制與隨時進入事業單位之權","第十五條及第十六條之規定，即封存抽取物料與聲請搜索扣押之職權","本法有關勞動檢查員之全部規定，於代行檢查員均一體適用而無例外"],"a",
 "第21條：第11條及第12條之規定，於代行檢查員適用之。第11條禁止檢查員為變更、隱匿或捏造事實之陳報、洩漏受檢查事業單位之生產技術設備及經營財務等秘密、洩漏秘密申訴案件之申訴來源、與受檢查事業單位發生不當財務關係；第12條則為利害關係之迴避規定。",
 "Which provisions on labor inspectors also apply to accredited inspectors?",
 ["Articles 11 and 12, that is the prohibited acts and recusal where there is an interest","Articles 13 and 14, that is the limits on advance notice and the right of free entry","Articles 15 and 16, that is sealing and sampling and applying for search and seizure","All provisions on labor inspectors apply to accredited inspectors without any exception"],
 "Article 21 of the Labor Inspection Act."),

(E,"第23條",2,"勞檢法-檢查程序",
 "勞動檢查員實施檢查認有必要邀請專家陪同鑑定時，應如何辦理？事業單位得否拒絕？",
 ["得報請所屬勞動檢查機構核准後，邀請相關主管機關、學術機構、團體或專家、醫師陪同前往鑑定，事業單位不得拒絕","得逕行邀請相關主管機關、學術機構、團體或專家、醫師陪同前往鑑定，惟事業單位認有正當理由者得予以拒絕","應報請中央主管機關核准後，指定經認可之顧問服務機構前往鑑定，其鑑定所需費用由受檢查之事業單位負擔","得於徵得事業單位書面同意後，邀請學術機構或專家陪同前往鑑定，並由勞動檢查機構負擔全部鑑定費用"],"a",
 "第23條第1項：勞動檢查員實施勞動檢查認有必要時，得報請所屬勞動檢查機構核准後，邀請相關主管機關、學術機構、相關團體或專家、醫師陪同前往鑑定，事業單位不得拒絕。第2項：第11條第1項第2款（洩漏生產技術、設備及經營財務等秘密之禁止）及第12條（迴避）之規定，於前項陪同人員適用之。",
 "How may an inspector bring experts along for appraisal, and may the enterprise refuse?",
 ["With approval of his agency he may invite agencies, institutions, groups, experts or doctors, and refusal is barred","He may invite agencies, institutions, groups, experts or doctors directly, but the enterprise may refuse with cause","With ministry approval he must designate an accredited consulting body, and the enterprise pays the appraisal cost","With the written consent of the enterprise he may invite institutions or experts, and the agency pays every cost"],
 "Article 23 of the Labor Inspection Act."),

(E,"第24條",1,"勞檢法-檢查程序",
 "勞動檢查機構辦理職業災害檢查、鑑定、分析等事項時，得由何者提供技術協助？",
 ["得由中央主管機關所屬勞動及職業安全衛生研究所或其他學術、研究機構提供必要之技術協助","得委由代行檢查機構或經認可之驗證機構提供必要之技術協助，其費用由事業單位負擔","應由中央主管機關指定之醫療機構及職業病防治中心提供鑑定所需之必要技術協助","得請求警察機關、消防機關及檢察機關派員提供職業災害原因鑑定之必要技術協助"],"a",
 "第24條：勞動檢查機構辦理職業災害檢查、鑑定、分析等事項，得由中央主管機關所屬勞動部勞動及職業安全衛生研究所或其他學術、研究機構提供必要之技術協助。第27條並定發生重大職業災害時，應立即指派勞動檢查員前往實施檢查，調查職業災害原因及責任。",
 "Who may give technical support for occupational accident inspection, appraisal and analysis?",
 ["The ministrys Institute of Labor, Occupational Safety and Health or other academic or research bodies","Accredited inspection bodies or approved verification bodies, with the enterprise paying the cost","Medical institutions and occupational disease centres designated by the central competent authority","The police, the fire service and the prosecutors office, on a request for cause determination help"],
 "Article 24 of the Labor Inspection Act."),

(E,"第30條",1,"勞檢法-停工復工",
 "經依第二十七條至第二十九條規定通知停工之事業單位，應如何申請復工？",
 ["得於停工之原因消滅後，向勞動檢查機構申請復工，由該機構查證後通知復工","得於停工滿七日後，逕向中央主管機關申請復工，無須經勞動檢查機構之同意","應於接獲停工通知之次日起十日內，向勞動檢查機構提出異議並一併申請復工","得於改善完成後自行復工，並於復工後十五日內函報勞動檢查機構備查即可"],"a",
 "第30條：經依第27條至第29條規定通知停工之事業單位，得於停工之原因消滅後，向勞動檢查機構申請復工。施行細則第36條並定勞動檢查機構於查證停工原因消滅後，應以書面通知其復工，復工通知書應記載申請復工之事業單位、雇主名稱及地址、復工日期及復工範圍。違反停工通知者，依第34條處三年以下有期徒刑。",
 "How may an enterprise ordered to stop work apply to resume?",
 ["After the cause of the stoppage ends, it applies to the inspection agency, which verifies and notifies","After seven days of stoppage, it applies directly to the ministry without the agencys agreement","Within ten days of the notice, it must object to the inspection agency and apply to resume at once","It may resume on its own once improved, and merely file a report with the agency within fifteen days"],
 "Article 30; see Enforcement Rules Article 36."),

(E,"第31條",2,"勞檢法-代行檢查",
 "代行檢查員於實施危險性機械或設備檢查後，對合格與不合格者應分別如何處理？",
 ["合格者應即於原合格證上簽署並註明有效期限；不合格者應告知事業單位並陳報所屬代行檢查機構函請勞動檢查機構處理","合格者應即發給新的檢查合格證並公告於機構網站；不合格者應逕予封存該機械設備並移送司法機關偵辦處理","合格者應報請勞動檢查機構核發合格證後生效；不合格者得由事業單位申請複檢一次，複檢仍不合格始應停用","合格者應於三十日內將檢查紀錄送交中央主管機關備查；不合格者應命事業單位於一個月內改善並自行複查"],"a",
 "第31條：代行檢查員進入事業單位實施檢查時，應主動出示代行檢查證，並告知雇主指派人員在場。檢查後合格者，應即於原合格證上簽署，註明有效期限；不合格者，應告知事業單位不合格事項，並陳報所屬代行檢查機構函請勞動檢查機構依法處理。不合格之危險性機械或設備，非經檢查合格，不得使用。代行檢查證由中央主管機關製發。",
 "How must an accredited inspector deal with passing and failing equipment?",
 ["If it passes he endorses the original certificate with a validity date; if not he informs the firm and reports up","If it passes he issues a new certificate and posts it online; if not he seals the equipment and refers for prosecution","If it passes the inspection agency issues the certificate; if not the firm may seek one re-inspection before any halt","If it passes he files the record with the ministry in thirty days; if not the firm improves and re-checks in a month"],
 "Article 31 of the Labor Inspection Act."),

(E,"第35條",2,"勞檢法-罰則",
 "事業單位無故拒絕、規避或妨礙勞動檢查員進入事業單位執行檢查職務者，應如何處罰？",
 ["處新臺幣三萬元以上十五萬元以下罰鍰，並得按次處罰","處新臺幣三萬元以上六萬元以下罰鍰，並得按次處罰之","處三年以下有期徒刑、拘役或科或併科十五萬元以下罰金","處新臺幣六萬元以上三十萬元以下罰鍰，情節重大者停工"],"a",
 "第35條：事業單位或行為人違反第14條第1項（不得無故拒絕、規避或妨礙勞動檢查員隨時進入事業單位）或第15條第2項（不得拒絕、規避或妨礙檢查員詢問、調閱文件、封存抽樣等行為）者，處新臺幣三萬元以上十五萬元以下罰鍰，並得按次處罰。第14條第2項並定非警察協助不足以排除時，得要求警察人員協助。",
 "How is an enterprise punished for refusing, evading or obstructing an inspectors entry without cause?",
 ["A fine of NT$30,000 to NT$150,000, and it may be imposed for each successive violation","A fine of NT$30,000 to NT$60,000, and it may be imposed for each successive violation","Up to three years imprisonment, detention, or a criminal fine of up to NT$150,000","A fine of NT$60,000 to NT$300,000, with a stop-work order where the case is serious"],
 "Article 35; see Articles 14 and 15."),

(E,"第36條",2,"勞檢法-罰則",
 "事業單位未將檢查結果於違規場所公告七日以上，或未公告勞工申訴相關事項者，應如何處罰？",
 ["處新臺幣三萬元以上六萬元以下罰鍰；有關團體違反第七條第二項規定者亦同","處新臺幣三萬元以上十五萬元以下罰鍰，並得按次處罰；有關團體違反者亦同","處新臺幣六萬元以上三十萬元以下罰鍰；並得限期令其改正，屆期未改正者停工","處三年以下有期徒刑、拘役或科或併科新臺幣十五萬元以下罰金；法人亦科罰金"],"a",
 "第36條：事業單位違反第25條第2項（檢查結果應於違規場所顯明易見處公告七日以上）或第32條第1項（公告受理申訴機構、申訴範圍、申訴書格式及申訴程序）者，處新臺幣三萬元以上六萬元以下罰鍰；有關團體違反第7條第2項（不得拒絕提供勞動檢查資料）者亦同。",
 "How is an enterprise punished for failing to post inspection results or the complaint notice?",
 ["A fine of NT$30,000 to NT$60,000; the same applies to a group breaching Article 7-2","A fine of NT$30,000 to NT$150,000 with repeat penalties; the same applies to such a group","A fine of NT$60,000 to NT$300,000, with an order to correct and a stoppage if it fails","Up to three years imprisonment or a criminal fine of NT$150,000; a legal person is fined too"],
 "Article 36; see Articles 25, 32 and 7."),

(E,"第37條",1,"勞檢法-罰則",
 "依勞動檢查法所處之罰鍰，經通知而逾期不繳納者，應如何處理？",
 ["經通知而逾期不繳納者，移送法院強制執行","經通知而逾期不繳納者，按日加徵其滯納金","經通知而逾期不繳納者，得逕予命令其停工","經通知而逾期不繳納者，移送司法機關偵辦"],"a",
 "第37條：依本法所處之罰鍰，經通知而逾期不繳納者，移送法院強制執行。本法之罰鍰規定包括第35條之三萬元以上十五萬元以下及第36條之三萬元以上六萬元以下；第34條之刑罰則另循刑事程序處理。",
 "What happens if a fine under the Act is not paid by the deadline after notice?",
 ["It is referred to the court for compulsory enforcement of the unpaid fine","A late payment surcharge is added for each day the fine remains unpaid","A stop-work order may be issued directly against the enterprise concerned","The case is referred to the judicial authorities for criminal investigation"],
 "Article 37 of the Labor Inspection Act."),

(E,"第38條",2,"勞檢法-附則",
 "本法修正施行前已依法令設立之危險性工作場所，應如何辦理？逾期不辦理者之效果為何？",
 ["應於中央主管機關指定期限內申請審查或檢查；逾期不辦理或審查、檢查不合格仍使勞工作業者，依第三十四條規定處罰","應於本法修正施行之日起一年內申請審查或檢查；逾期不辦理者，由勞動檢查機構逕予通知全部停工並對外公告之","得繼續使勞工作業，僅須於中央主管機關指定期限內補行申報，逾期未申報者處新臺幣六萬元以下之罰鍰","應報請當地主管機關核准後始得繼續作業；經審查或檢查不合格者，應自行停工並於改善後申請複查合格"],"a",
 "第38條：本法修正施行前已依法令設立之屬第26條所定危險性工作場所，應於中央主管機關指定期限內，申請該管勞動檢查機構審查或檢查；逾期不辦理或審查、檢查不合格，而仍使勞工在該場所作業者，依第34條規定處罰，即處三年以下有期徒刑、拘役或科或併科新臺幣十五萬元以下罰金。",
 "What must pre-existing dangerous workplaces do, and what follows if they miss the deadline?",
 ["Apply for review or inspection within the period the ministry sets; letting workers in late or unfit draws Article 34","Apply within one year of the amended Act taking effect; if late, the agency orders a full stoppage and announces it","They may keep operating and merely file a late declaration; failing that draws a fine of up to NT$60,000","They must obtain municipal approval to continue; if they fail the review they stop and seek a re-inspection"],
 "Article 38; the penalty is that of Article 34."),

(E,"第39條",1,"勞檢法-附則",
 "勞動檢查法施行細則之訂定機關為何？",
 ["本法施行細則，由中央主管機關定之，現行細則並定有危險物數量附表","本法施行細則，由行政院定之，並送立法院查照後發布施行以昭公信","本法施行細則，由各直轄市主管機關分別定之，報請中央主管機關核定","本法施行細則，由中央主管機關會同經濟部及內政部共同會銜訂定發布"],"a",
 "第39條：本法施行細則，由中央主管機關定之。現行勞動檢查法施行細則第1條即載明本細則依本法第39條規定訂定之；其第29條並定本法第26條第1項第5款所稱危險物、有害物之數量，依附表一及附表二之規定。",
 "Which authority issues the Enforcement Rules of the Labor Inspection Act?",
 ["The central competent authority; the current rules also carry annexes on hazardous quantities","The Executive Yuan, which files them with the Legislative Yuan before they are promulgated","Each municipal competent authority separately, subject to approval by the central authority","The central authority jointly with the economics and interior ministries under a joint signature"],
 "Article 39 of the Labor Inspection Act."),

(E,"第40條",1,"勞檢法-附則",
 "勞動檢查法之施行日期規定為何？",
 ["本法自公布日施行，未另授權以命令定其施行日期","本法自公布後三個月施行，以利各界完成準備作業","本法施行日期，由中央主管機關以命令定之並公告","本法自公布後一年施行，其施行細則同日發布施行"],"a",
 "第40條：本法自公布日施行。與職業安全衛生法第55條規定施行日期由行政院定之者不同。施行細則第41條則定該細則自發布日施行，其中華民國一百零三年六月二十六日修正條文自一百零三年七月三日施行。",
 "When does the Labor Inspection Act take effect?",
 ["On the date of promulgation, with no separate order fixing an effective date","Three months after promulgation, so that all parties can complete preparations","On a date the central competent authority fixes by order and then announces","One year after promulgation, with its enforcement rules issued the same day"],
 "Article 40; compare Article 55 of the OSH Act."),

# ===== 勞動檢查法施行細則 =====
(D,"第7條",2,"勞檢細則-檢查資料",
 "勞動檢查機構得向有關團體請求提供之勞動檢查資料範圍為何？勞動檢查年報應何時公布？",
 ["包括事業單位、雇主之名稱（姓名）、地址、電話、勞工人數等資料；年報應於每年第三季公布前一年者","包括事業單位之財務報表、營業額及股東名冊等資料；年報應於每年第一季公布前一年之檢查結果","包括勞工之姓名、身分證統一編號及薪資明細等資料；年報應於每年年底前公布當年度之檢查結果","包括事業單位之機械設備清冊及製程資料等；年報應於每二年公布一次前二年之勞動檢查統計數據"],"a",
 "第7條：勞動檢查機構依本法第7條第1項規定得向有關團體請求提供之勞動檢查資料，包括事業單位、雇主之名稱（姓名）、地址、電話、勞工人數及其他相關資料。中央主管機關依本法第7條第3項規定，應於每年第三季公布前一年之勞動檢查年報。有關團體拒絕提供者，依本法第36條處三萬元以上六萬元以下罰鍰。",
 "What inspection data may be requested from related groups, and when is the annual report published?",
 ["Names, addresses, phone numbers and worker numbers of enterprises and employers; the report comes in Q3","Financial statements, turnover and shareholder lists of the enterprise; the report comes in the first quarter","Worker names, national ID numbers and pay details; the report on the current year comes before year end","Machinery inventories and process data of the enterprise; statistics are published once every two years"],
 "Article 7 of the Enforcement Rules."),

(D,"第8條",1,"勞檢細則-檢查員",
 "本法第九條所稱勞動檢查員之專業訓練，其內容包括哪些？",
 ["指新進人員之職前訓練、現職人員之在職訓練及進修等三者","指新進人員之職前訓練及每三年一次之複訓，不含在職進修","指經中央主管機關委託學術機構辦理之碩士以上學位之進修","指現職人員每年不得少於三十小時之在職訓練及技能檢定"],"a",
 "第8條：本法第9條所稱專業訓練，指新進人員之職前訓練、現職人員之在職訓練及進修。第9條並定新進勞動檢查員未經職前訓練合格前，勞動檢查機構不得指派其單獨執行檢查職務；但特殊情況，經勞動檢查機構敘明理由陳報中央主管機關核准者，不在此限。",
 "What does professional training under Article 9 of the Act include?",
 ["Pre-service training for new staff, plus in-service training and further study for serving staff","Pre-service training for new staff and a refresher every three years, without further study","Study for a masters degree or above at institutions commissioned by the central authority","At least thirty hours of in-service training and a skills test each year for serving staff"],
 "Article 8 of the Enforcement Rules."),

(D,"第10條",2,"勞檢細則-檢查程序",
 "勞動檢查員依本法第十三條第一款規定通知事業單位檢查行程前，應先確認何事？",
 ["應確認事業單位依本法第二十六條或第三十八條申請審查或檢查之文件已完成查核，且檢查日期業經勞動檢查機構排定","應確認事業單位申請危險性機械或設備檢查之文件已完成查核，且經事業單位書面同意接受檢查後始得通知行程","應先完成事業單位發生職業災害之登錄，並經中央主管機關核准後，始得通知該事業單位其檢查之行程日期","應經事業單位所在地直轄市主管機關同意，並將檢查日期於七日前公告於勞動檢查機構網站供各界查詢"],"a",
 "第10條：勞動檢查員依本法第13條第1款規定通知事業單位檢查行程，應確認事業單位依本法第26條或第38條規定之申請審查或檢查之文件已完成查核，檢查日期業經勞動檢查機構排定後為之。本法第13條規定除該款之審查或檢查、危險性機械設備檢查、職業災害檢查及其他經核准者外，不得事先通知事業單位。",
 "What must be confirmed before notifying an enterprise of an inspection under Article 13-1?",
 ["That the Article 26 or 38 review or inspection documents are checked and the date has been scheduled","That the dangerous machinery application documents are checked and the enterprise has agreed in writing","That the occupational accident has first been logged and the central authority has given its approval","That the municipal authority agrees and the date is posted on the agency website seven days ahead"],
 "Article 10 of the Enforcement Rules."),

(D,"第11條",2,"勞檢細則-檢查程序",
 "勞動檢查員依本法第十三條第二款規定通知事業單位檢查行程前，應先確認何事？",
 ["應確認事業單位申請危險性機械或設備檢查之文件已完成查核，且檢查日期業經勞動檢查機構排定後為之","應確認事業單位申請危險性工作場所審查之文件已完成查核，且經中央主管機關核准後始得為之","應於事業單位提出申請後三日內通知檢查行程，並由代行檢查機構會同勞動檢查員共同實施檢查","應先完成事業單位職業災害之登錄，並經該事業單位工會同意後，始得通知其檢查行程日期"],"a",
 "第11條：勞動檢查員依本法第13條第2款規定通知事業單位檢查行程，應確認事業單位申請危險性機械或設備檢查之文件已完成查核，檢查日期業經勞動檢查機構排定後為之。第10條所定者為第13條第1款之審查或檢查，第12條所定者則為第13條第3款之職業災害檢查。",
 "What must be confirmed before notifying an inspection under Article 13-2 of the Act?",
 ["That the dangerous machinery or equipment application has been checked and the date scheduled","That the dangerous workplace review documents are checked and the ministry has approved it","That notice is given within three days of the application and an accredited inspector joins in","That the occupational accident is logged and the enterprise union has given its consent first"],
 "Article 11 of the Enforcement Rules."),

(D,"第12條",1,"勞檢細則-檢查程序",
 "勞動檢查員依本法第十三條第三款規定通知事業單位職業災害檢查行程前，應先辦理何事？",
 ["應事前完成事業單位發生職業災害之登錄後，始得通知其檢查行程","應事前取得罹災勞工或其家屬之書面同意後，始得通知檢查之行程","應事前報請中央主管機關核准，並副知目的事業主管機關後為之","應事前確認事業單位已依規定申請審查或檢查之文件查核完成後為之"],"a",
 "第12條：勞動檢查員依本法第13條第3款規定通知事業單位檢查行程，應事前完成事業單位發生職業災害之登錄後為之。本法第13條所列得事先通知之事項共四款：第26條之審查或檢查、危險性機械或設備檢查、職業災害檢查，及其他經勞動檢查機構或主管機關核准者。",
 "What must be done before notifying an enterprise of an occupational accident inspection?",
 ["The occupational accident of that enterprise must first be logged before notice is given","The written consent of the injured worker or the family must be obtained before notice","Approval must be sought from the ministry and a copy sent to the line ministry first","The review or inspection application documents must first be confirmed as checked"],
 "Article 12 of the Enforcement Rules."),

(D,"第14條",2,"勞檢細則-封存",
 "勞動檢查員實施封存時，應辦理之程序及封條應記載事項為何？",
 ["應開列封存物件清單及貼封條；封條應加蓋勞動檢查機構印信，並載明機構名稱、封存物件名稱、封存日期及法令依據","應開列封存物件清單並經事業單位簽章；封條應由檢查員親自簽名，並載明檢查員姓名、編號及其封存之原因等事項","應報請勞動檢查機構核准後貼封條；封條應加蓋機構印信，並載明啟封條件、保管人姓名及其聯絡方式等相關事項","應會同警察人員開列清單後貼封條；封條應載明封存物件之名稱、數量、價值及事業單位負責人姓名等必要事項"],"a",
 "第14條：勞動檢查員依本法第15條第1項第4款規定實施封存時，應開列封存物件清單及貼封條；封條應加蓋勞動檢查機構印信，並載明勞動檢查機構名稱、封存物件名稱、封存日期及法令依據。第13條並定封存以違反職安法令禁止使用、違反勞動法令、職業災害原因鑑定所必須或其他經勞動檢查機構核准者為限，其原因消滅或經許可者得啟封。",
 "What procedure applies to sealing, and what must the seal state?",
 ["List the sealed items and affix a seal bearing the agency chop, its name, the item, the date and the legal basis","List the items with the enterprises signature; the inspector signs the seal, stating his name, number and reason","Seal only after agency approval; the seal bears the agency chop and states unsealing terms and a custodian","List the items with police present; the seal states the item name, quantity, value and the employers name"],
 "Article 14; see also Article 13 on grounds for sealing."),

(D,"第16條",1,"勞檢細則-搜索扣押",
 "勞動檢查員依本法第十六條規定執行搜索、扣押時，應依何種法律規定辦理？",
 ["應依刑事訴訟法之相關規定辦理，包括搜索票之聲請與其執行程序","應依行政執行法之相關規定辦理，並由勞動檢查機構逕行決定之","應依勞動檢查法施行細則所定之封存程序辦理，並開列清單存查","應依警察職權行使法之相關規定，會同警察人員實施搜索及扣押"],"a",
 "第16條：勞動檢查員依本法第16條之規定執行搜索、扣押，應依刑事訴訟法相關規定。本法第16條定勞動檢查員對違反勞動法律規定之犯罪嫌疑者，必要時得聲請檢察官簽發搜索票，就其相關物件、處所執行搜索、扣押。此與第15條第1項第4款之封存程序不同。",
 "Which law governs search and seizure by a labor inspector under Article 16?",
 ["The Code of Criminal Procedure, including applying for and executing a search warrant","The Administrative Execution Act, with the inspection agency deciding on its own motion","The sealing procedure of these Enforcement Rules, with an inventory drawn up for record","The Police Power Exercise Act, with police officers joining in the search and the seizure"],
 "Article 16 of the Enforcement Rules."),

(D,"第17條",1,"勞檢細則-代行檢查",
 "得由代行檢查機構指派代行檢查員實施之危險性機械或設備檢查，指哪些檢查？",
 ["指定期檢查及其他經中央主管機關指定公告之檢查等項目","指熔接檢查、構造檢查及竣工檢查等出廠前之檢查項目","指重新檢查、變更檢查及使用檢查等異動時之檢查項目","指危險性工作場所之審查、檢查及其後之定期查核項目"],"a",
 "第17條：本法第17條所定得由代行檢查機構指派代行檢查員實施之具有危險性之機械或設備檢查，指定期檢查及其他經中央主管機關指定公告之檢查。職業安全衛生法施行細則第24條所列檢查項目包括熔接檢查、構造檢查、竣工檢查、定期檢查、重新檢查、型式檢查、使用檢查及變更檢查。",
 "Which inspections may accredited inspectors carry out on dangerous machinery or equipment?",
 ["Periodic inspections and any other inspection the central authority designates and announces","Welding, construction and completion inspections, that is checks before the item leaves works","Re-inspection, alteration inspection and use inspection, that is checks on any change of status","Review and inspection of dangerous workplaces and the periodic audits that follow that review"],
 "Article 17 of the Enforcement Rules."),

(D,"第18條",1,"勞檢細則-代行檢查",
 "受指定之代行檢查機構如為行政機關，其代行檢查範圍有何限制？",
 ["其代行檢查範圍以所屬事業所有之具有危險性之機械或設備為限","其代行檢查範圍及於轄區內所有事業單位之危險性機械或設備","其代行檢查範圍以經中央主管機關個案指定之事業單位設備為限","其代行檢查範圍以定期檢查為限，不得辦理其他類別檢查項目"],"a",
 "第18條：依本法第17條受指定之代行檢查機構為行政機關者，其代行檢查範圍以所屬事業所有之具有危險性之機械或設備為限。本法第3條第2款定代行檢查機構得為行政機關、學術機構或非營利法人；第31條並定代行檢查員實施檢查時應主動出示代行檢查證。",
 "What limit applies where the designated accredited inspection body is a government agency?",
 ["Its inspections are limited to dangerous machinery or equipment owned by its own enterprises","Its inspections extend to the dangerous machinery of every enterprise within its jurisdiction","Its inspections are limited to enterprises designated case by case by the central authority","Its inspections are limited to periodic inspections and may not cover other categories"],
 "Article 18 of the Enforcement Rules."),

(D,"第19條",1,"勞檢細則-檢查程序",
 "勞動檢查員依本法第二十二條規定進入事業單位進行檢查前，應辦理何事？",
 ["應將檢查目的告知雇主及工會，並請其派員陪同實施檢查","應將檢查項目函知雇主，並由工會指定人員全程錄影存證","應於檢查前三日以書面通知雇主及工會，並取得其書面同意","應先向工會說明檢查範圍，雇主無正當理由不得派員在場"],"a",
 "第19條：勞動檢查員依本法第22條規定進入事業單位進行檢查前，應將檢查目的告知雇主及工會，並請其派員陪同。本法第22條第1項並定檢查員應主動出示勞動檢查證，並告知雇主及工會；事業單位對未持勞動檢查證者，得拒絕檢查。",
 "What must an inspector do before entering an enterprise under Article 22 of the Act?",
 ["Tell the employer and the union the purpose of the inspection and ask them to send someone along","Send the employer a list of items and have the union assign someone to film the whole inspection","Give the employer and union written notice three days ahead and obtain their written agreement","Explain the scope to the union first; the employer may not send anyone along without good cause"],
 "Article 19 of the Enforcement Rules."),

(D,"第20條",2,"勞檢細則-檢查證",
 "勞動檢查證之換發期間及應記載事項為何？",
 ["每二年換發一次，離職時應繳回，並貼照片及載明所屬單位名稱、姓名職稱編號、檢查法令依據及範圍、使用期限","每三年換發一次，離職時應繳回，並貼照片及載明所屬單位名稱、姓名及檢查範圍，惟無須記載其使用之期限","每年換發一次，離職時得繼續持有，並載明檢查員之專長領域、訓練時數及所屬檢查機構首長之姓名職稱","每五年換發一次，遺失時應公告作廢，並載明檢查法令依據、檢查區域及其得單獨執行檢查之項目範圍"],"a",
 "第20條：勞動檢查證每二年換發一次，勞動檢查員離職時應繳回。勞動檢查證應貼勞動檢查員之照片，並記載所屬單位名稱、姓名、職稱及編號、檢查法令依據及檢查範圍、使用期限。第38條並定本條規定於本法第31條第4項之代行檢查證適用之；勞動檢查證由中央主管機關製發。",
 "How often is the inspection certificate renewed, and what must it state?",
 ["Every two years and returned on leaving; it bears a photo, the unit, name, title, number, legal basis, scope and term","Every three years and returned on leaving; it bears a photo, the unit, the name and the scope, but not the term","Every year and may be kept after leaving; it states the inspectors specialty, training hours and the agency head","Every five years and voided by announcement if lost; it states the legal basis, area and items he may do alone"],
 "Article 20; applied to accredited inspection certificates by Article 38."),

(D,"第22條",1,"勞檢細則-檢查結果",
 "本法第二十五條第二項所稱應於違規場所公告之檢查結果，係指何者？",
 ["指勞動檢查機構向事業單位所發立即改正或限期改善之檢查結果通知書","指勞動檢查員於檢查現場所作成並經雇主簽章確認之檢查紀錄表冊","指勞動檢查機構所為之罰鍰處分書及其違反法令條文之明細表件","指中央主管機關每年定期公布之勞動檢查年報所載之各項統計結果"],"a",
 "第22條：本法第25條第2項所稱檢查結果，指勞動檢查機構向事業單位所發立即改正或限期改善之檢查結果通知書。本法第25條第2項定事業單位對檢查結果，應於違規場所顯明易見處公告七日以上；違反者依第36條處三萬元以上六萬元以下罰鍰。公告方式則見第23條。",
 "What are the inspection results that must be posted under Article 25-2 of the Act?",
 ["The notice of inspection results ordering immediate correction or improvement within a period","The inspection record made at the site and signed and confirmed by the employer on the spot","The written fine decision of the inspection agency and the schedule of provisions breached","The statistics contained in the annual labor inspection report published by the ministry"],
 "Article 22; see Article 23 on how to post it."),

(D,"第24條",2,"勞檢細則-定義",
 "本法第二十六條至第二十八條所稱之工作場所，其定義為何？",
 ["指勞動契約存續中，勞工履行契約提供勞務時，由雇主或代理雇主指示處理有關勞工事務之人所能支配、管理之場所","指事業單位向主管機關登記之營業場所及其附屬之倉庫、宿舍、餐廳等由雇主所有並供勞工使用之全部場所","指勞工實際從事作業之特定區域，不包括通道、休息室及其他非直接從事生產作業之附屬空間在其範圍內","指經勞動檢查機構認定具有危險性，並以書面通知事業單位列管之特定作業區域及其周邊之相鄰範圍"],"a",
 "第24條：本法第26條至第28條所稱工作場所，指於勞動契約存續中，勞工履行契約提供勞務時，由雇主或代理雇主指示處理有關勞工事務之人所能支配、管理之場所。第26條為危險性工作場所之審查檢查，第27條為重大職業災害之停工，第28條為勞工有立即發生危險之虞之先行停工。",
 "How are workplaces defined for Articles 26 to 28 of the Act?",
 ["Places controlled or managed by the employer or the person directed to handle labor affairs during the contract","The registered business premises of the enterprise and its warehouses, dormitories and canteens for workers","Only the specific area where work is done, excluding passageways, rest rooms and other ancillary spaces","Areas the inspection agency has deemed dangerous and listed by written notice, plus the adjoining area"],
 "Article 24 of the Enforcement Rules."),

(D,"第25條",1,"勞檢細則-危險性工作場所",
 "本法第二十六條第一項第一款所稱從事石油裂解之石化工業之工作場所，指何者？",
 ["指從事石油產品之裂解反應，以製造石化基本原料之工作場所","指從事原油之常壓蒸餾及減壓蒸餾，以製造燃料油之工作場所","指從事石化基本原料之聚合反應，以製造塑膠原料之工作場所","指設置高壓氣體類壓力容器並儲存石油產品之大型儲槽工作場所"],"a",
 "第25條：本法第26條第1項第1款所稱石油裂解之石化工業之工作場所，係指從事石油產品之裂解反應，以製造石化基本原料之工作場所。職業安全衛生法施行細則第21條亦援引本款定義本法第15條第1項第1款之從事石油裂解之石化工業。",
 "What is a workplace of the petrochemical industry engaged in petroleum cracking?",
 ["A workplace where petroleum products are cracked to produce basic petrochemical feedstock","A workplace where crude oil is distilled at atmospheric and reduced pressure to make fuel oil","A workplace where basic petrochemical feedstock is polymerised to produce plastics resins","A workplace with high pressure gas vessels and large tanks storing petroleum products"],
 "Article 25 of the Enforcement Rules."),

(D,"第26條",2,"勞檢細則-危險性工作場所",
 "本法第二十六條第一項第二款所稱之農藥製造工作場所，指何者？",
 ["指使用異氰酸甲酯、氯化氫、氨、甲醛、過氧化氫或吡啶為原料，從事農藥原體合成之工作場所","指使用有機磷、氨基甲酸鹽或除蟲菊精類為原料，從事農藥成品分裝及包裝之工作場所","指使用氯酸鹽類、過氯酸鹽類、硝酸鹽類或硫化物為原料，從事農藥製劑調配之工作場所","指經中央主管機關指定公告，其農藥年產量達一定數量以上之製造工廠及其倉儲場所"],"a",
 "第26條：本法第26條第1項第2款所稱農藥製造工作場所，係指使用異氰酸甲酯、氯化氫、氨、甲醛、過氧化氫或吡啶為原料，從事農藥原體合成之工作場所。此類危險性工作場所非經勞動檢查機構審查或檢查合格，事業單位不得使勞工在該場所作業，違者依本法第34條處罰。",
 "What is an agricultural chemicals manufacturing workplace under Article 26-1-2?",
 ["A site synthesising pesticide active ingredients from methyl isocyanate, HCl, ammonia, formaldehyde or pyridine","A site repacking and packaging finished pesticides made from organophosphates, carbamates or pyrethroids","A site formulating pesticide preparations from chlorates, perchlorates, nitrates or sulphide compounds","A factory and its warehouses designated by the ministry whose annual pesticide output exceeds a set level"],
 "Article 26 of the Enforcement Rules."),

(D,"第27條",2,"勞檢細則-危險性工作場所",
 "本法第二十六條第一項第三款所稱之爆竹煙火工廠，指何者？",
 ["指利用氯酸鹽類、過氯酸鹽類、硝酸鹽類、硫、硫化物、磷化物、木炭粉、金屬粉末及其他原料製造爆竹煙火類物品之工廠","指利用有機過氧化物、硝化纖維、賽璐珞、乙醚、二硫化碳及其他易燃物質從事煙火藥劑分裝作業之工廠","指利用氨、氯化氫、甲醛、過氧化氫、吡啶及其他化學品從事爆竹引信與導火索製造作業之工廠","指經內政部核准登記，且其從業人員在三十人以上並設有專用儲藏庫之爆竹煙火販賣及儲存場所"],"a",
 "第27條：爆竹煙火工廠，係指利用氯酸鹽類、過氯酸鹽類、硝酸鹽類、硫、硫化物、磷化物、木炭粉、金屬粉末及其他原料製造爆竹煙火類物品之工廠；同條並定火藥類製造工作場所，係指從事以化學物質製造爆炸性物品之工作場所。二者均屬本法第26條第1項第3款之危險性工作場所。",
 "What is a fireworks factory under Article 26-1-3 of the Act?",
 ["A factory making fireworks from chlorates, perchlorates, nitrates, sulphur, sulphides, phosphides, charcoal and metal powders","A factory repacking pyrotechnic compositions using organic peroxides, nitrocellulose, celluloid, ether and carbon disulphide","A factory making fireworks fuses and safety cords using ammonia, hydrogen chloride, formaldehyde, peroxide and pyridine","A licensed fireworks sale and storage site with thirty or more staff and a dedicated storage magazine on the premises"],
 "Article 27; explosives manufacturing workplaces are defined in the same article."),

(D,"第28條",3,"勞檢細則-危險性工作場所",
 "本法第二十六條第一項第四款所稱之容量，其認定標準為何？",
 ["蒸汽鍋爐傳熱面積五百平方公尺以上，或高壓氣體類壓力容器一日冷凍能力一百五十公噸以上，或處理能力一千立方公尺以上之氧氣、有毒性或可燃性高壓氣體","蒸汽鍋爐傳熱面積三百平方公尺以上，或高壓氣體類壓力容器一日冷凍能力一百公噸以上，或處理能力五百立方公尺以上之氧氣、有毒性或可燃性高壓氣體","蒸汽鍋爐傳熱面積一千平方公尺以上，或高壓氣體類壓力容器一日冷凍能力三百公噸以上，或處理能力五千立方公尺以上之有毒性或可燃性之高壓氣體","蒸汽鍋爐傳熱面積五百平方公尺以上，或高壓氣體類壓力容器一日冷凍能力五十公噸以上，或處理能力一百立方公尺以上之氧氣及其他各類高壓氣體"],"a",
 "第28條：所稱容量，指蒸汽鍋爐之傳熱面積在五百平方公尺以上，或高壓氣體類壓力容器一日之冷凍能力在一百五十公噸以上或處理能力符合下列規定之一者：一千立方公尺以上之氧氣、有毒性或可燃性高壓氣體；五千立方公尺以上之前款以外之高壓氣體。第27條之1並定高壓氣體類壓力容器及蒸汽鍋爐之意義。",
 "What capacity thresholds apply under Article 26-1-4 of the Act?",
 ["Boiler heating surface of 500 m2 or more, refrigeration capacity of 150 t/day or more, or 1,000 m3 of oxygen or toxic or flammable gas","Boiler heating surface of 300 m2 or more, refrigeration capacity of 100 t/day or more, or 500 m3 of oxygen or toxic or flammable gas","Boiler heating surface of 1,000 m2 or more, refrigeration capacity of 300 t/day or more, or 5,000 m3 of toxic or flammable high pressure gas","Boiler heating surface of 500 m2 or more, refrigeration capacity of 50 t/day or more, or 100 m3 of oxygen and other high pressure gases"],
 "Article 28; see Article 27-1 for the definitions."),

(D,"第29條",1,"勞檢細則-危險性工作場所",
 "本法第二十六條第一項第五款所稱危險物、有害物之數量，應如何認定？",
 ["依本細則附表一及附表二之規定認定其數量","依中央主管機關每年公告之運作量清單認定","依國家標準CNS 15030分類之危害級別認定","依事業單位安全資料表所載之貯存數量認定"],"a",
 "第29條：本法第26條第1項第5款所稱危險物、有害物之數量，依附表一及附表二之規定。職業安全衛生法施行細則第21條第2項亦援引本款，作為職業安全衛生法第15條第1項第2款危害性化學品數量之認定依據。",
 "How are the quantities of dangerous and harmful substances determined?",
 ["By the quantities listed in Annexes 1 and 2 to these Enforcement Rules","By the annual list of handling volumes announced by the central authority","By the hazard category assigned under the CNS 15030 national classification","By the storage volume stated in the safety data sheet held by the enterprise"],
 "Article 29 of the Enforcement Rules."),

(D,"第30條",1,"勞檢細則-刪除條文",
 "勞動檢查法施行細則第三十條之現行狀態為何？",
 ["業經刪除而無規範內容；危險物、有害物之數量現依第二十九條附表認定","仍屬有效，規定危險性工作場所應每五年重新申請審查或檢查各一次","仍屬有效，規定甲類工作場所之審查申請書應載明事項及檢附之文件","業經刪除，惟其原定之審查通過有效期間規定仍繼續適用於既設場所"],"a",
 "第30條：（刪除）。現行條文並無內容。危險物、有害物之數量依第29條附表一及附表二認定；重大職業災害之類型則規定於第31條，包括死亡災害、罹災三人以上、氨氯氟化氫光氣硫化氫二氧化硫等洩漏致一人以上需住院治療及其他經指定公告之災害。",
 "What is the current status of Article 30 of these Enforcement Rules?",
 ["Deleted with no content; hazardous substance quantities are set by the annexes to Article 29","Still in force, requiring dangerous workplaces to reapply for review every five years","Still in force, setting what a Class A workplace review application must state and attach","Deleted, yet its rule on how long an approval stays valid still applies to existing sites"],
 "Article 30 was deleted; see Articles 29 and 31."),

(D,"第32條",1,"勞檢細則-刪除條文",
 "本細則第三十二條目前有無規範內容？",
 ["已刪除而無內容；重大職業災害之類型係規定於本細則第三十一條","仍有內容，規定停工日數之計算方式及應陳報中央主管機關之情形","仍有內容，規定職業災害檢查應於災害發生後二十四小時內實施","已刪除，惟其原定之罹災人數計算方式仍應依原條文之規定辦理"],"a",
 "第32條：（刪除）。本法第27條所稱重大職業災害，依第31條係指發生死亡災害、罹災人數在三人以上、氨氯氟化氫光氣硫化氫二氧化硫等化學物質洩漏致一人以上罹災勞工需住院治療，及其他經中央主管機關指定公告之災害。停工日數則規定於第33條，全部停工超過七日者應陳報中央主管機關核定。",
 "Does Article 32 of these Enforcement Rules still have content?",
 ["No, it is deleted; the kinds of major occupational accident are set out in Article 31","Yes, it sets how stoppage days are counted and when the ministry must be asked to approve","Yes, it requires an accident inspection to be carried out within twenty-four hours","No, it is deleted, but its way of counting the injured still applies as originally written"],
 "Article 32 was deleted; see Articles 31 and 33."),

(D,"第34條",2,"勞檢細則-停工",
 "本法第二十七條至第二十九條之停工通知書，應記載哪些事項？",
 ["受停工處分事業單位、雇主名稱及地址、法令依據、停工理由、停工日期、停工範圍、申請復工之條件及程序、執行停工處分之機構","受停工處分事業單位及雇主之名稱與地址、罹災勞工姓名與人數、災害發生原因、預定復工日期及應改善事項等相關必要事項","事業單位名稱及地址、違反之法令條文、罰鍰金額、繳納期限、行政救濟途徑及受理異議之機關名稱等應載明事項","停工範圍之圖說或照片、事業單位負責人身分證字號、工會名稱、勞工人數及最近一次之檢查結果等應載事項"],"a",
 "第34條：停工通知書應記載受停工處分事業單位、雇主名稱（姓名）及地址、法令依據、停工理由、停工日期、停工範圍、申請復工之條件及程序、執行停工處分之機構等八款事項；其中停工範圍必要時得以圖說或照片註明。第35條並定必要時得於停工範圍張貼停工通知書並標示停工區域。",
 "What must a stop-work notice under Articles 27 to 29 state?",
 ["The enterprise and employer name and address, legal basis, reason, dates, scope, resumption terms and the issuing body","The enterprise and employer name and address, the injured workers and numbers, the cause, a resumption date and fixes","The name and address, the provisions breached, the fine amount, the payment deadline and the appeal channels","Drawings or photos of the scope, the responsible persons ID number, the union, worker numbers and the last result"],
 "Article 34 of the Enforcement Rules."),

(D,"第35條",1,"勞檢細則-停工",
 "勞動檢查機構以書面通知事業單位停工後，於必要時尚得為何種作為？",
 ["得於停工範圍張貼停工通知書，並得以顯明之警告或禁止之標誌標示停工區域","應於停工範圍張貼停工通知書七日以上，並由事業單位派員二十四小時看守","應由勞動檢查機構會同警察機關於停工區域拉起封鎖線，禁止任何人員進入","得將停工通知書公告於勞動檢查機構之網站，以代替於停工範圍之現場張貼"],"a",
 "第35條：勞動檢查機構依本法第27條至第29條規定以書面通知事業單位部分或全部停工，於必要時得於停工範圍張貼停工通知書，並得以顯明之警告或禁止之標誌標示停工區域。第33條並定停工日數由勞動檢查機構視情節決定，全部停工日數超過七日者應陳報中央主管機關核定。",
 "What further step may the agency take after issuing a written stop-work notice?",
 ["Post the stop-work notice within the scope and mark the area with conspicuous warning or prohibition signs","Post the notice within the scope for at least seven days and have the enterprise guard it around the clock","Cordon off the area together with the police so that no person at all may enter the stopped area","Publish the notice on the agency website in place of posting it at the site of the stoppage itself"],
 "Article 35 of the Enforcement Rules."),

(D,"第37條",2,"勞檢細則-代行檢查",
 "代行檢查員實施危險性機械或設備檢查後，對於不合格者應如何處理？",
 ["應即於原檢查合格證記事欄或其他必要文件內記載不合格情形，作成紀錄，並經會同人員簽章","應即收繳原檢查合格證並註銷之，作成紀錄後於三日內函報中央主管機關核備並對外公告","應即於現場貼附禁止使用標誌，並會同事業單位人員將該設備封存後移交勞動檢查機構","應即通知事業單位限期改善，並於改善期限屆滿後實施複檢，複檢合格者始補行簽署"],"a",
 "第37條：代行檢查員於實施危險性機械或設備之檢查後，對不合格者應即於原檢查合格證記事欄或其他必要文件內記載不合格情形，作成紀錄，並經會同人員簽章。本法第31條第2項並定不合格者應告知事業單位不合格事項，並陳報所屬代行檢查機構函請勞動檢查機構依法處理；不合格之機械設備非經檢查合格不得使用。",
 "How must an accredited inspector deal with equipment that fails the inspection?",
 ["Note the failure at once in the remarks column of the certificate or other papers, record it and have witnesses sign","Take back and cancel the certificate at once, record it and report to the ministry within three days for publication","Affix a prohibition label on the spot and, with the enterprise staff, seal the item and hand it to the agency","Order the enterprise to improve within a period and re-inspect afterwards, endorsing it only if it then passes"],
 "Article 37; see also Article 31 of the Act."),

(D,"第20條、第38條",1,"勞檢細則-代行檢查",
 "本法第三十一條第四項所定之代行檢查證，準用本細則何條規定？",
 ["準用第二十條關於勞動檢查證之規定，即每二年換發一次並應記載一定事項","準用第十九條關於檢查前告知之規定，應於檢查前告知雇主及工會其目的","準用第二十三條關於公告方式之規定，應於事業單位顯明易見處公告七日","並無準用規定，代行檢查證之格式及有效期限由各代行檢查機構自行訂定"],"a",
 "第38條：第20條之規定，於本法第31條第4項代行檢查證適用之。故代行檢查證亦每二年換發一次，離職時應繳回，並應貼照片及記載所屬單位名稱、姓名職稱及編號、檢查法令依據及檢查範圍、使用期限。代行檢查證由中央主管機關製發。",
 "Which article applies to the accredited inspection certificate under Article 31-4 of the Act?",
 ["Article 20 on inspection certificates, so it is renewed every two years and states set particulars","Article 19 on prior notice, so the employer and union must be told the purpose before inspection","Article 23 on posting, so it must be displayed at a conspicuous place in the enterprise for a week","None; each accredited inspection agency decides the format and the validity period for itself"],
 "Article 38; it applies Article 20."),

(D,"第39條",2,"勞檢細則-申訴公告",
 "本法第三十二條所定申訴事項公告書之張貼場所及方式為何？",
 ["應張貼於第二十三條第一款所定場所；字體大小、張貼高度及位置應適於勞工清晰閱讀，並為永久張貼，污損時應即更換","應張貼於違反規定之機具、設備或場所；字體及高度由事業單位自行決定，並至少每七日檢視一次有無污損之情形","應張貼於事業單位大門及各出入口；公告書應經護貝並加蓋勞動檢查機構印信，且每年更新一次以維持其效力","應公告於事業單位內部網站及公布欄；並由工會負責維護，其公告內容變更時應報請勞動檢查機構備查後實施"],"a",
 "第39條：本法第32條所稱顯明而易見之場所，指第23條第1款規定之場所，即事業單位管制勞工出勤之場所、餐廳宿舍及各作業場所之公告場所，或與工會或勞工代表協商同意之場所。張貼公告書時，字體大小、張貼高度及位置應適於勞工能清晰閱讀為原則，並為永久張貼，污損時應即更換。",
 "Where and how must the worker complaint notice under Article 32 be posted?",
 ["At the places in Article 23-1; the size, height and position must let workers read it, posted permanently and replaced when soiled","At the machine, equipment or site in breach; the enterprise decides the size and height and checks it for damage every seven days","At the main gate and every entrance; the notice must be laminated, bear the agency chop and be renewed once a year to stay valid","On the intranet and the notice board; the union maintains it and any change of content is filed with the inspection agency first"],
 "Article 39; see Article 23, Subparagraph 1."),

(D,"第40條",1,"勞檢細則-刪除條文",
 "本細則第四十條之現行效力為何？",
 ["業經刪除，其所屬之第六章亦已刪除，現行細則自第四十一條規定施行日期","仍屬有效，規定事業單位對檢查結果通知書提出異議之期間及其應載事項","仍屬有效，規定勞動檢查機構應將檢查結果按季彙報中央主管機關備查","業經刪除，惟其原定之罰鍰裁量基準仍由勞動檢查機構參照適用至今日"],"a",
 "第40條：（刪除）。其所屬之第六章亦已刪除。事業單位對檢查結果通知書有異議者，依第21條應於通知書送達之次日起十日內以書面敘明理由向勞動檢查機構提出，且改善期限不因異議而停止計算。第41條則為本細則之施行日期規定。",
 "What is the current effect of Article 40 of these Enforcement Rules?",
 ["It is deleted, as is its chapter; the current rules move straight to Article 41 on the effective date","It remains in force, setting the period and contents for objecting to a notice of inspection results","It remains in force, requiring agencies to report inspection results to the ministry each quarter","It is deleted, yet its guidelines on setting fine amounts are still followed by inspection agencies"],
 "Article 40 was deleted; see Articles 21 and 41."),

(D,"第41條",1,"勞檢細則-施行",
 "勞動檢查法施行細則之施行日期規定為何？",
 ["本細則自發布日施行；一百零三年六月二十六日修正條文自同年七月三日施行","本細則自發布後三個月施行；一百零三年修正條文自一百零四年一月一日施行","本細則之施行日期由中央主管機關另定之；其修正條文自發布後六個月施行","本細則自勞動檢查法公布之日施行；歷次修正條文均自發布之次日起生效"],"a",
 "第41條：本細則自發布日施行；本細則中華民國一百零三年六月二十六日修正條文，自一百零三年七月三日施行。該日亦為職業安全衛生法及其施行細則之施行日，係配合勞動檢查法第2條所稱危險性機械或設備援引職業安全衛生法第16條之修正而定。",
 "When do these Enforcement Rules take effect?",
 ["On promulgation; the amendments of 26 June 2014 took effect on 3 July of the same year","Three months after promulgation; the 2014 amendments took effect on 1 January 2015","On a date set separately by the ministry; amendments take effect six months after issue","On the day the Labor Inspection Act was promulgated; amendments take effect the next day"],
 "Article 41 of the Enforcement Rules."),

]
